    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint amount) public payable {
        require(amount >= 0);
        uint bal0 = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint eth0 = address(c).balance;
        c.withdraw(); if (__ESBMC_reverted()) return;
        uint bal1 = c.balances(address(this)); if (__ESBMC_reverted()) return;
        c.withdraw(); if (__ESBMC_reverted()) return;
        uint bal2 = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint eth2 = address(c).balance;
        assert(bal1 == 0 && bal2 == 0 && eth2 <= eth0 + amount * 0 && eth2 >= eth0 - amount * 0);
    }
    receive() external payable {}
